import * as THREE from 'three';
let shared;
export function concreteFoundation(){if(shared)return shared;let map=null;if(typeof document!=='undefined'){const canvas=document.createElement('canvas');canvas.width=512;canvas.height=256;const c=canvas.getContext('2d');c.fillStyle='#70756c';c.fillRect(0,0,512,256);let seed=3281;const rand=()=>((seed=(Math.imul(seed,1664525)+1013904223)>>>0)/4294967296);for(let i=0;i<130;i++){const x=rand()*512,y=rand()*256;c.fillStyle=i%2?'#414a4020':'#a4aa9520';c.beginPath();c.ellipse(x,y,12+rand()*65,3+rand()*17,(rand()-.5)*.3,0,Math.PI*2);c.fill();}c.fillStyle='#313e3430';c.beginPath();c.moveTo(0,256);for(let x=0;x<=512;x+=8)c.lineTo(x,183+Math.sin(x*.027)*19+Math.sin(x*.071)*9);c.lineTo(512,256);c.fill();for(let i=0;i<8000;i++){c.fillStyle=i%3?'#242e2514':'#c9c8ad1a';c.fillRect(rand()*512,rand()*256,.5+rand()*1.5,.5+rand()*1.5);}map=new THREE.CanvasTexture(canvas);map.colorSpace=THREE.SRGBColorSpace;map.wrapS=THREE.RepeatWrapping;map.wrapT=THREE.ClampToEdgeWrapping;}shared=new THREE.MeshStandardMaterial({name:'Worn concrete DampFoundation',map,color:map?'#c2c5bc':'#62685f',roughness:1,metalness:0});return shared;}
export function fixFoundation(root){root.updateMatrixWorld(true);root.traverse(mesh=>{if(!mesh.isMesh||Array.isArray(mesh.material)||!/dampfoundation/i.test(mesh.material.name))return;mesh.material=concreteFoundation();mesh.geometry=mesh.geometry.clone();const p=mesh.geometry.attributes.position,uv=mesh.geometry.attributes.uv,point=new THREE.Vector3();if(!uv)return;for(let i=0;i<p.count;i++){point.fromBufferAttribute(p,i).applyMatrix4(mesh.matrixWorld);uv.setXY(i,point.x/6,Math.max(0,Math.min(1,point.y/.6)));}uv.needsUpdate=true;});}
